const J=globalThis.window?.jarvis;
if(J&&(new URLSearchParams(location.search).get('view')||'main')==='main'){
 const api=(method,data={})=>J.call('core',{method,data}),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let panel,state,masked=false,previous,busy=false,opening=false;
 const say=s=>{if(panel)panel.querySelector('[role=status]').textContent=s;};
 async function close(){if(busy)return;panel?.remove();panel=null;if(masked)await J.call('tabs-show',true).catch(()=>{});masked=false;window.__jarvisHolo?.pauseAll(false);previous?.focus?.();}
 async function show(){if(panel||opening)return;opening=true;try{state=await api('meeting-work');previous=document.activeElement;masked=await J.call('tabs-state').catch(()=>false);if(masked)await J.call('tabs-show',false);window.__jarvisHolo?.pauseAll(true);panel=document.createElement('section');panel.className='wb-panel';panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-label','Meeting work');panel.innerHTML='<header><div><small>AFTER THE MEETING</small><h2>Meeting work</h2></div><button data-act="close">Close</button></header><div class="wb-body"><main></main></div><p class="wb-status" role="status"></p>';document.body.append(panel);panel.onclick=e=>{const b=e.target.closest('[data-act]');if(b)run(b).catch(e=>say(e.message));};panel.onsubmit=e=>{e.preventDefault();submit(e.target).catch(e=>say(e.message));};draw();panel.querySelector('button').focus();}catch(e){await close();alert(e.message);}finally{opening=false;}}
 const area=(k,v)=>`<label>${k}<textarea name="${k}" rows="2" required>${esc(v)}</textarea></label>`;
 function draw(){panel.querySelector('main').innerHTML=`<p>Stop a recorded meeting to prepare work from its transcript. JARVIS matches your actual suit descriptions and floor expertise. Ideas are suggestions; unclear work waits for your answers. Email follow-ups still need your approval in Routines.</p>${state.error?`<p>${esc(state.error)}</p>`:''}<details><summary>Starting work · ${state.config.autoStart?'automatic internal drafts':'review first'}</summary><form data-config><label class="wm-fast"><input type="checkbox" name="autoStart" ${state.config.autoStart?'checked':''}> Start clear, complete internal tasks automatically after new meetings</label><label>Estimated agent allowance per new meeting (US$)<input name="perMeeting" type="number" min="0.1" max="10" step="0.1" value="${state.config.perMeeting}"></label><p>Reserves this allowance across tasks within the Core daily budget. Requires a Claude API key. Meeting notes use their existing separate summary allowance. Agents prepare text drafts only; external actions and app changes wait for review. Actual provider prices can differ from estimates.</p><button>Save starting preference</button></form></details><button data-act="refresh">Refresh progress</button>${state.meetings.map(m=>`<article class="wb-item"><h3>${esc(m.suit)} · ${new Date(m.at).toLocaleString('en-GB')}</h3><p>Estimated agent allowance $${m.allowance.toFixed(2)} · reserved $${m.reserved.toFixed(2)}</p>${m.tasks.length?m.tasks.map(p=>`<details><summary>${esc(p.title)} · ${esc(p.kind)} · ${esc(p.status)}</summary><p>${esc(p.suitName||'Suit to confirm')} → ${esc(p.floorName||'Floor to confirm')}</p><p>${esc(p.reason)}</p><blockquote>“${esc(p.evidence)}”</blockquote>${p.questions.length?`<h4>Needs your input</h4><ul>${p.questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ul>`:''}${p.error||p.saveError||p.result?`<p>${esc(p.error||p.saveError||p.result)}</p>`:''}${p.runId?`<button data-act="tower" data-theme="${esc(p.theme)}" data-run="${esc(p.runId)}">Open agent work</button>`:p.kind==='idea'?'<p>Saved in Think. Suggestions are not automatically executed.</p>':!p.authorised&&!p.attempted&&p.status!=='dismissed'?`<form data-task data-meeting="${esc(m.id)}" data-id="${p.id}"><label>Suit<select name="suit" required><option value="">Choose suit</option>${state.catalog.suits.map(s=>`<option value="${esc(s.theme+':'+s.id)}" ${s.id===p.suitId&&s.theme===p.theme?'selected':''}>${esc(s.name+' · '+s.theme)}</option>`).join('')}</select></label><label>Floor<select name="floor" required><option value="">Choose floor</option>${state.catalog.floors.map(f=>`<option value="${esc(f.theme+':'+f.id)}" ${f.id===p.floorId&&f.theme===p.theme?'selected':''}>${esc(f.name+' · '+f.theme)}</option>`).join('')}</select></label>${['outcome','audience','files','constraints','finished'].map(k=>area(k,p.brief[k])).join('')}<label>Your answers or corrections<textarea name="answers" rows="3" ${p.questions.length?'required':''}>${esc(p.answers||'')}</textarea></label><button>Save reviewed task</button></form>`:p.authorised&&!p.runId?'<p>Queued for a free floor and available allowance.</p>':''}${p.proposalId?'<button data-act="proposal">Open proposal drafts</button>':''}${!p.runId&&!p.attempted&&p.kind!=='idea'&&p.status!=='dismissed'?`<button data-act="dismiss" data-meeting="${esc(m.id)}" data-id="${p.id}">Dismiss task</button>`:''}</details>`).join(''):'<p>No evidenced follow-through items were identified. The transcript and meeting notes remain available.</p>'}${m.tasks.some(p=>p.status==='ready'&&!p.authorised)?`<button class="wb-primary" data-act="request" data-id="${esc(m.id)}">Review starting these tasks</button>`:''}</article>`).join('')||'<p>No meeting work yet. Start Meeting mode before the call, then stop transcription when it finishes.</p>'}`;}
 async function guard(fn){if(busy)return;busy=true;panel.querySelectorAll('button').forEach(b=>b.disabled=true);try{return await fn();}finally{busy=false;panel?.querySelectorAll('button').forEach(b=>b.disabled=false);}}
 async function refresh(){state=await api('meeting-work');draw();}
 async function submit(form){const p=Object.fromEntries(new FormData(form));await guard(async()=>{if(form.hasAttribute('data-config')){await api('save',{meetingWork:{autoStart:!!p.autoStart,perMeeting:Number(p.perMeeting)}});say('Starting preference saved for future meetings.');}else{const[theme,suitId]=p.suit.split(':'),[floorTheme,floorId]=p.floor.split(':');if(theme!==floorTheme)throw Error('Choose a suit and floor in the same hall.');await api('meeting-work-edit',{meeting:form.dataset.meeting,id:form.dataset.id,theme,suitId,floorId,answers:p.answers,brief:Object.fromEntries(['outcome','audience','files','constraints','finished'].map(k=>[k,p[k]]))});say('Task saved. Review starting it when ready.');}await refresh();});}
 async function run(b){if(busy)return;const act=b.dataset.act;if(act==='close')return close();if(act==='tower'){await close();return window.__jarvisTower?.showRun(b.dataset.theme,b.dataset.run);}if(act==='proposal'){await close();return window.__jarvisWorkDesk?.show('proposals');}if(act==='request'){const r=await guard(()=>api('meeting-work-request',{id:b.dataset.id}));if(r){await close();await window.__jarvisCore?.show('needs');}return;}await guard(async()=>{if(act==='dismiss')await api('meeting-work-skip',{meeting:b.dataset.meeting,id:b.dataset.id});await refresh();});}
 addEventListener('keydown',e=>{if(!panel)return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();close();}if(e.key==='Tab'){const a=[...panel.querySelectorAll('button,input,select,textarea,summary')].filter(e=>e.getClientRects().length&&!e.disabled);if(e.shiftKey&&document.activeElement===a[0]){e.preventDefault();a.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===a.at(-1)){e.preventDefault();a[0]?.focus();}}},true);
 const sync=()=>{const nav=document.querySelector('.wb-panel .wb-filters');if(!nav?.textContent.includes('Meeting follow-ups')||nav.querySelector('[data-meeting-work]'))return;const b=document.createElement('button');b.textContent='Meeting work';b.dataset.meetingWork='';b.onclick=async()=>{await window.__jarvisRoutines?.close();await show();};nav.append(b);};const timer=setInterval(sync,1000);window.__jarvisMeetingWork={show,close};addEventListener('pagehide',()=>clearInterval(timer));
}
